import re,sys
KW=r'^(?:@\[[^\]]*\]\s*)?(?:private |protected |noncomputable )?(def|abbrev|structure|inductive|instance|class)\s+(\S+)'
def defs(path):
    lines=open(path).read().split('\n'); res={}; cur=None; buf=[]
    starts=re.compile(r'^(theorem|example|def|abbrev|structure|inductive|instance|class|@\[|/--|/-!|section|end|namespace|open|variable|private|protected|noncomputable|deriving|attribute)\b')
    for ln in lines:
        m=re.match(KW,ln)
        if m:
            if cur: res[cur]='\n'.join(buf).strip()
            cur=m.group(2); buf=[ln]; continue
        if cur and starts.match(ln) and not ln.startswith('deriving'):
            res[cur]='\n'.join(buf).strip(); cur=None; buf=[]; continue
        if cur: buf.append(ln)
    if cur: res[cur]='\n'.join(buf).strip()
    return res
a=defs(sys.argv[1]); b=defs(sys.argv[2])
print('defs',len(a),len(b))
print('removed',[n for n in a if n not in b])
print('changed',[n for n in a if n in b and a[n]!=b[n]])
print('added',[n for n in b if n not in a])
EOF
